// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint96 _value, address _target, bytes memory _data) public {
        vm.assume(_target != address(0) && _target != address(c) && _target.code.length == 0);
        vm.deal(address(c), _value);
        uint balBefore = _target.balance;
        vm.prank(c.owner());
        (bool success,) = address(c).call(abi.encodeWithSelector(c.sendMoney.selector, _target, _value, _data));
        if(success) {
            assertTrue(_target.balance == balBefore + _value);
        } else {
            assertTrue(true);
        }
    }
}
